-- ==============================================================
-- 出发口岸精确到区/县级（A 方案：区县数据直接导入现有 city_info，不新建表）
--   0. 修正 city_info 中滁州市的错误区划码 331100 -> 341100
--      （331100 实为浙江丽水市，两行共用会导致按市过滤区县时串数据）
--   1. 幂等清理：删除本脚本此前导入的区县行
--   2. 导入全国区县级行政区划（数据源：统计用区划代码 province-city-china 离线包）
--      已剔除 281 条「市辖区」分类占位行（码形如 130101），只导入真实区/县/县级市
--   3. 验证
-- 约定：
--   * 区县行 remarks = '区县级' / '区县级(省直辖)'，
--     原有 348 条市级行 remarks 为 直辖市/省会城市/地级市，可据此区分层级；
--   * 层级不建 parent 列，由区划码推导：父市码 = 区县码前4位 + '00'，
--     命不中且省码为 11/12/31/50 时归到对应直辖市（库里直辖市存省级码 110000 等）；
--   * 区县 city_english_name = 区县自身专名的大写连写拼音（如 浦东新区->PUDONG、
--     义乌市->YIWU），风格与现有市级行一致；民族名与通名（区/县/市/旗/新区）不入英文；
--   * 济源市/石河子市等已作为市级行存在的码不重复导入。
-- ==============================================================

SET NAMES utf8mb4;

-- 0. 修正滁州市区划码（幂等：仅在错误码仍存在时生效）
UPDATE `city_info` SET `city_code` = '341100', `update_time` = NOW()
WHERE `city_name` = '滁州市' AND `city_code` = '331100';

-- 1. 清理历史导入的区县行（可重复执行本脚本）
DELETE FROM `city_info` WHERE `remarks` LIKE '区县级%';

