-- 3. 验证
SELECT `remarks`, COUNT(*) AS 行数 FROM `city_info` GROUP BY `remarks` ORDER BY 行数 DESC;
SELECT COUNT(*) AS 区县总数, COUNT(DISTINCT LEFT(`city_code`, 4)) AS 覆盖市数
FROM `city_info` WHERE `remarks` LIKE '区县级%';
SELECT `city_code`, `city_name`, `city_english_name`, `province_name` FROM `city_info`
WHERE `city_name` IN ('浦东新区', '滁州市', '丽水市', '北仑区', '琅琊区') ORDER BY `city_code`;
-- 按市取区县（示例：上海市 310000 存的是省级码，故用前缀 31 兜底）
SELECT `city_code`, `city_name` FROM `city_info`
WHERE `remarks` LIKE '区县级%' AND LEFT(`city_code`, 4) = '3101' ORDER BY `sort`;
